-- BKKARI TECH V21
create table if not exists digital_service_orders (id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,order_number text not null unique,satofill_order_id text not null,product_id text not null,product_name text not null,quantity int not null default 1,custom_fields jsonb not null default '{}'::jsonb,total numeric(12,2) not null default 0,currency text not null default 'USD',status text not null default 'processing',response_data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists digital_service_orders_user_idx on digital_service_orders(user_id,created_at desc);
alter table digital_service_orders enable row level security;drop policy if exists "users read own digital service orders" on digital_service_orders;create policy "users read own digital service orders" on digital_service_orders for select to authenticated using(auth.uid()=user_id);
create or replace function debit_wallet_for_service(p_user_id uuid,p_amount numeric,p_reference text) returns table(ok boolean,message text,new_balance numeric) language plpgsql security definer set search_path=public as $$declare b numeric;begin if p_amount<0 then return query select false,'قيمة غير صحيحة',0::numeric;return;end if;select balance into b from wallets where user_id=p_user_id for update;b:=coalesce(b,0);if b<p_amount then return query select false,'رصيد المحفظة غير كافي',b;return;end if;update wallets set balance=balance-p_amount,updated_at=now() where user_id=p_user_id;insert into wallet_transactions(user_id,amount,type,status,reference) values(p_user_id,-p_amount,'purchase','pending',p_reference);select balance into b from wallets where user_id=p_user_id;return query select true,'تم الخصم',b;end;$$;
revoke all on function debit_wallet_for_service(uuid,numeric,text) from public;grant execute on function debit_wallet_for_service(uuid,numeric,text) to service_role;
insert into site_settings(key,value) values('wallet_payment',jsonb_build_object('method','شام كاش','account_name','BKKARI TECH','account_number','','image_url','','note','حوّل المبلغ عبر شام كاش ثم تواصل مع الإدارة وأرسل رقم العملية والإيصال.')) on conflict(key) do update set value=coalesce(site_settings.value,'{}'::jsonb)||jsonb_build_object('method','شام كاش'),updated_at=now();
